// SECI FDRE-X: the RfS's bid formats (Section 7, RfS printed pp. 65-107, PDF pp. 66-108) and the
// annexures a bidder hands in (Annexure-A, C, H and K, PDF pp. 109-139), as data: which formats
// a bid needs, who signs each, on what paper, in which envelope, and every blank with the words
// that stand beside it on its page. Plain JavaScript with no imports, checked in Node by
// tools/check_fdrex_content.mjs (every heading and every blank's context is found on the PDF page
// it cites). Pages below are PDF pages of web/public/tenders/seci-fdre-x/RfS.pdf (the printed
// page + 1: the PDF has a cover first).
//
// A blank's `maps` names where its value comes from: a value of the bid (contractedMw, solarMw,
// bessMwh, emdAmount, rfsNo...) or a particular asked once and used in every format (bidder,
// address, signatory...), by the names the CfD formats use; null is a blank only this format has.
// Two names are this tender's: `psm` (the bid's choice of cover under the Payment Security
// Mechanism, the model's input of that name) and `cacAmount`, which here is the Success Charges.
// The logic that fills, counts and reviews the formats is shared between the tenders and is not
// in this file.
//
// What differs from the CfD formats: the EMD and the PBG may also be a Payment on Order
// Instrument of REC or PFC (Formats 7.3B and 7.3E, `applies` "emd-poi" and "pbg-poi"); the
// Covering Letter carries the choice of cover under the payment security mechanism and encloses
// the connectivity application; Format 7.12 goes in the financial envelope; and Annexure-K is
// needed when the connectivity is another entity's.

export const RFS_FILE = "/tenders/seci-fdre-x/RfS.pdf";

/** The `applies` values the formats use (the CfD ones, plus the five this RfS needs: Format 7.8 gives way to 7.8A, RfS 5.1 note). */
export const APPLIES = ["always", "consortium", "emd-bg", "emd-poi", "emd-surety", "pbg-bg", "pbg-poi", "pbg-surety", "common-shareholding", "no-common-shareholding", "third-party-connectivity", "after-award"];

/** The PDF pages the formats and the annexures may cite for a blank: Section 7 to Annexure-K. */
export const FORMAT_PAGES = [66, 139];

const ctx = (page, quote) => ({ doc: "rfs", page, quote });
const F = (key, label, kind, maps, page, quote, extra = {}) => ({ key, label, kind, maps, context: ctx(page, quote), ...extra });

// the particulars every letter head shares: name and address, the RfS reference, the date and signatory
const HEAD = (page, { ref = "Ref. No. _________", from = "(Insert name and address of Bidding Company/ Lead Member of", tel = "Tel.#:", sub = "Sub: Response to RfS No." } = {}) => [
  F("refNo", "Reference number", "text", null, page, ref),
  F("date", "Letter date", "date", "date", page, "Date: ___________"),
  F("bidder", "Bidding Company / Lead Member name", "text", "bidder", page, from),
  F("address", "Bidder address", "textarea", "address", page, from),
  F("phone", "Telephone", "text", "phone", page, tel),
  F("email", "E-mail", "text", "email", page, "E-mail address#"),
  F("rfsNo", "RfS number", "text", "rfsNo", page, sub),
  F("rfsDate", "RfS date", "date", "rfsDate", page, sub),
  F("title", "RfS title", "text", "title", page, sub),
];
const SIGN = (page) => [
  F("signatory", "Authorised signatory (name, designation)", "text", "signatory", page, "Name, Designation, Seal and Signature of Authorized Person in whose name Power of"),
];

